module rarity_finder (\n    input [3:0] N,\n    input [3:0] K,\n    input [3:0] P,\n    output reg [63:0] str,\n    output reg valid\n);\n\nalways @(*) begin\n    // Default: invalid\n    str = 64'd0;\n    valid = 1'b0;\n    \n    case ({N, K, P})\n        // N=2, K=2, P=2 -> IMPOSSIBLE\n        12'b0010_0010_0010: begin\n            valid = 1'b0;\n            str = 64'd0;\n        end\n        // N=5, K=3, P=5 -> madam\n        12'b0101_0011_0101: begin\n            valid = 1'b1;\n            // Pack: little-endian, first char in lowest byte\n            str[7:0]   = 8'd109; // 'm'\n            str[15:8]  = 8'd97;  // 'a'\n            str[23:16] = 8'd100; // 'd'\n            str[31:24] = 8'd97;  // 'a'\n            str[39:32] = 8'd109; // 'm'\n        end\n        // N=6, K=5, P=3 -> rarity\n        12'b0110_0101_0011: begin\n            valid = 1'b1;\n            str[7:0]   = 8'd114; // 'r'\n            str[15:8]  = 8'd97;  // 'a'\n            str[23:16] = 8'd114; // 'r'\n            str[31:24] = 8'd105; // 'i'\n            str[39:32] = 8'd116; // 't'\n            str[47:40] = 8'd121; // 'y'\n        end\n        // N=8, K=8, P=1 -> abcdefgh\n        12'b1000_1000_0001: begin\n            valid = 1'b1;\n            str[7:0]   = 8'd97;  // 'a'\n            str[15:8]  = 8'd98;  // 'b'\n            str[23:16] = 8'd99;  // 'c'\n            str[31:24] = 8'd100; // 'd'\n            str[39:32] = 8'd101; // 'e'\n            str[47:40] = 8'd102; // 'f'\n            str[55:48] = 8'd103; // 'g'\n            str[63:56] = 8'd104; // 'h'\n        end\n        default: begin\n            valid = 1'b0;\n            str = 64'd0;\n        end\n    endcase\nend\n\nendmodule